    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "must_exit_with_cart",
    "text": "The agent is obligated to leave the store while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The agent is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_at_3_1",
    "text": "The agent is prohibited from being at cell (3,1) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_upper_column",
    "text": "The agent is prohibited from taking a cart into cells (3,1) or (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_north_with_cart_from_3_3",
    "text": "The agent is prohibited from moving north from cell (3,3) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_at_3_3",
    "text": "Whenever the agent is at cell (3,3) without a cart, the agent is obligated to have a cart again later.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "hasCart"
    }
  }
